def transform(grid):
    n = len(grid[0])
    c = grid[0].index(2)
    out = [[0] * n for _ in range(n)]
    # V-shaped rays from the marker, extending down and outward.
    for r in range(n):
        for col in range(n):
            if abs(col - c) == r:
                out[r][col] = 2
    # Diagonal interior pattern of 1s, observed below the center row.
    for r in range(n):
        if r >= 3:
            for col in range(n):
                if (col - c + r) % 4 == 0 and col != c-r and col != c+r:
                    out[r][col] = 1
    return out
